// Generate fuzzed timestamps in microseconds.
srs_utime_t start = *FUZZ_PARAM(srs_utime_t);
srs_utime_t end = *FUZZ_PARAM(srs_utime_t);

// Occasionally force either endpoint to zero to exercise the documented special-case path.
if ((*FUZZ_PARAM(unsigned int) & 1u) != 0u) { start = 0; }
if ((*FUZZ_PARAM(unsigned int) & 1u) != 0u) { end = 0; }

// Invoke target function.
srs_utime_t got = srs_time_since(start, end);

// Validate documented behavior:
// - If either start or end is zero, the function must return zero.
if (start == 0 || end == 0) {
    FUZZ_ASSERT(got == 0, "srs_time_since: when start or end is zero, result must be zero");
} else {
    // Otherwise it should be exactly end - start (may be negative).
    FUZZ_ASSERT(got == (end - start), "srs_time_since: result must equal end - start when both are non-zero");
}

// Validation: Exercises both zero and non-zero branches and asserts the documented properties.

// Harness SrsUniquePtr<int> constructor. Ensure ptr matches deleter rules.
// Choose whether to pass a null pointer or a valid new-allocated int.
bool make_null = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
int *raw = NULL;
if (!make_null) {
    raw = new int(*FUZZ_PARAM(int));
}
// Optionally supply a custom deleter; when provided, it correctly uses delete on int*.
bool use_custom_del = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
void (*del)(int*) = NULL;
if (use_custom_del) {
    del = +[](int *p){ delete p; };
}
// Construct the smart pointer object on the heap so the fuzzer can manage its lifetime via opaque void*.
SrsUniquePtr<int> *holder = new SrsUniquePtr<int>(raw, del);
void *uptr = (void*)holder;
// Track metadata for downstream stubs.
FUZZ_SET_ATTR_STR(uptr, "kind", "unique_single_int");
// Validation: The holder now owns raw and will delete with either provided deleter or delete; null ptr allowed.

// Destructor must match the kind created by the corresponding constructor.
const char *kind = FUZZ_GET_ATTR_STR(uptr, "kind");
if (!kind || kind[0] == '\0') { FUZZ_BAIL(); }
// Only accept single-object unique pointer here.
if (std::string(kind) != std::string("unique_single_int")) { FUZZ_BAIL(); }
SrsUniquePtr<int> *holder = (SrsUniquePtr<int>*)uptr;
// Deleting the holder will run the proper deleter (custom or delete).
delete holder;
// Validation: No outputs returned; ownership fully released.

// get() must not transfer ownership; we return the smart pointer back to the pool.
if (std::string(FUZZ_GET_ATTR_STR(uptr, "kind")) != std::string("unique_single_int")) { FUZZ_BAIL(); }
SrsUniquePtr<int> *holder = (SrsUniquePtr<int>*)uptr;
int *p = holder->get();
// Caller must not free p; we don't dereference without checking non-NULL.
if (p && ((*FUZZ_PARAM(unsigned int)) & 1)) {
    // Optionally read the value to exercise pointer validity without modifying ownership.
    volatile int sink = *p;
    (void)sink;
}
// Validation: Ownership unchanged; uptr is returned as output.

// Harness SrsUniquePtr<int[]> array constructor. Ensure ptr allocated with new[].
// Randomly choose to create a NULL or a valid array with size in [1, 64].
bool make_null = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
size_t n = (size_t)(*FUZZ_PARAM(unsigned int) % 64u) + 1u;
int *arr = NULL;
if (!make_null) {
    arr = new int[n];
    // Optionally initialize some elements.
    for (size_t i = 0; i < n && i < 8; ++i) {
        arr[i] = *FUZZ_PARAM(int);
    }
}
SrsUniquePtr<int[]> *holder = new SrsUniquePtr<int[]>(arr);
void *uptr_arr = (void*)holder;
FUZZ_SET_ATTR_STR(uptr_arr, "kind", "unique_array_int");
FUZZ_SET_ATTR_INT(uptr_arr, "size", (int) (make_null ? 0 : (int)n));
// Validation: Array pointer is new[]-allocated or NULL; specialization will delete[] it on destruction.

// Ensure correct specialization is being destroyed.
if (std::string(FUZZ_GET_ATTR_STR(uptr_arr, "kind")) != std::string("unique_array_int")) { FUZZ_BAIL(); }
SrsUniquePtr<int[]> *holder = (SrsUniquePtr<int[]>*)uptr_arr;
delete holder;
// Validation: Holder deletion triggers delete[] on managed array if non-NULL.

// get() should return the raw array pointer; do not free it here.
if (std::string(FUZZ_GET_ATTR_STR(uptr_arr, "kind")) != std::string("unique_array_int")) { FUZZ_BAIL(); }
SrsUniquePtr<int[]> *holder = (SrsUniquePtr<int[]>*)uptr_arr;
int *p = holder->get();
int sz = FUZZ_GET_ATTR_INT(uptr_arr, "size");
// Optionally touch up to one element if non-NULL and size > 0.
if (p && sz > 0 && ((*FUZZ_PARAM(unsigned int)) & 1)) {
    size_t idx = (size_t)(*FUZZ_PARAM(unsigned int) % (unsigned)sz);
    volatile int sink = p[idx];
    (void)sink;
}
// Validation: Ownership remains with holder; uptr_arr returned.

// Indexed access requires non-NULL managed array and in-bounds index.
if (std::string(FUZZ_GET_ATTR_STR(uptr_arr, "kind")) != std::string("unique_array_int")) { FUZZ_BAIL(); }
SrsUniquePtr<int[]> *holder = (SrsUniquePtr<int[]>*)uptr_arr;
int *p = holder->get();
int sz = FUZZ_GET_ATTR_INT(uptr_arr, "size");
if (!p || sz <= 0) { FUZZ_BAIL(); }
size_t idx = (size_t)(*FUZZ_PARAM(unsigned int) % (unsigned)sz);
// Property: idx is guaranteed within [0, sz).
FUZZ_ASSERT(idx < (size_t)sz, "index must be within bounds");
// Exercise both read and write paths.
int v = holder->operator[](idx);
if (((*FUZZ_PARAM(unsigned int)) & 1) != 0) {
    holder->operator[](idx) = v ^ *FUZZ_PARAM(int);
}
// Validation: Access performed only when pointer non-NULL and index in bounds; uptr_arr returned.

// Harness SrsSharedPtr<int> constructor. delete is the only supported deleter.
bool make_null = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
int *raw = NULL;
if (!make_null) {
    raw = new int(*FUZZ_PARAM(int));
}
SrsSharedPtr<int> *holder = new SrsSharedPtr<int>(raw);
void *sptr = (void*)holder;
FUZZ_SET_ATTR_STR(sptr, "kind", "shared_int");
// Validation: Reference count initialized appropriately; sptr handed to pool.

// Ensure we are destroying a matching shared pointer instance.
if (std::string(FUZZ_GET_ATTR_STR(sptr, "kind")) != std::string("shared_int")) { FUZZ_BAIL(); }
SrsSharedPtr<int> *holder = (SrsSharedPtr<int>*)sptr;
delete holder;
// Validation: Decrements ref-count and deletes managed int when last reference is gone.

// get() returns raw pointer without altering ownership.
if (std::string(FUZZ_GET_ATTR_STR(sptr, "kind")) != std::string("shared_int")) { FUZZ_BAIL(); }
SrsSharedPtr<int> *holder = (SrsSharedPtr<int>*)sptr;
int *p = holder->get();
if (p && ((*FUZZ_PARAM(unsigned int)) & 1)) {
    volatile int sink = *p;
    (void)sink;
}
// Validation: No ownership change; sptr returned.

// Copy assignment: both pointers may be NULL-managed. Maintain both in the pool after assignment.
if (std::string(FUZZ_GET_ATTR_STR(sptr_dst, "kind")) != std::string("shared_int")) { FUZZ_BAIL(); }
if (std::string(FUZZ_GET_ATTR_STR(sptr_src, "kind")) != std::string("shared_int")) { FUZZ_BAIL(); }
SrsSharedPtr<int> *dst = (SrsSharedPtr<int>*)sptr_dst;
SrsSharedPtr<int> *src = (SrsSharedPtr<int>*)sptr_src;
// Optionally test self-assignment path.
if (((*FUZZ_PARAM(unsigned int)) & 1) && dst != src) {
    // Make a temporary copy to increase coverage of copy/move semantics.
    SrsSharedPtr<int> tmp(*src);
    *dst = tmp;
} else {
    *dst = *src;
}
// Validation: After assignment, both dst and src remain valid shared pointer objects; both returned.

// Default-construct a new context id and ensure it starts empty.
_SrsContextId* ctx = new _SrsContextId();
// Property: default-constructed should be empty.
FUZZ_ASSERT(ctx->empty(), "_SrsContextId default constructor should create empty id");
// Track liveness for downstream stubs.
FUZZ_SET_ATTR_INT(ctx, "alive", 1);

// Prepare distinct source/target states to exercise assignment.
std::string s1 = FUZZ_PARAM_STR();
std::string s2 = FUZZ_PARAM_STR();
if (s2 == s1) { s2.push_back('\n'); }
