if (mode == 1u) {
    // Self-assignment must be a no-op semantically.
    _SrsContextId& ret = self->operator=(*self);
    FUZZ_ASSERT(&ret == self, "operator= should return *this on self-assign");
    FUZZ_ASSERT(self->compare(*self) == 0, "self-assignment should leave object equal to itself");
