// Do not return the object to the pool; ownership is released here.

// Obtain a stable C string view and validate basic properties.
const char* p = ctx->c_str();
// The pointer must be non-null by std::string::c_str contract.
FUZZ_ASSERT(p != NULL, "c_str() must return non-null pointer");
size_t len = 0; while (p[len] != '\0') { ++len; }
bool is_empty = ctx->empty();
// If empty() is true, c_str() must be an empty string.
