// If not empty, length should be > 0.
FUZZ_ASSERT(is_empty || len > 0, "non-empty() implies c_str length > 0");
// Do not modify ctx after obtaining p; keep pointer validity.

// Simply query emptiness; no preconditions.
bool e = ctx->empty();
// Touch the value to avoid optimizing away.
if (e) {
    // Optionally, observe c_str consistency when empty.
    const char* p = ctx->c_str();
    FUZZ_ASSERT(p != NULL, "c_str non-null");
}

